    lines.append("    /** As chaves de um dict, pela ordem em que foram escritas. */")
    lines.append("    private org.json.JSONArray _apkpyKeys(String json) {")
    lines.append("        org.json.JSONArray keys = new org.json.JSONArray();")
    lines.append("        try {")
