    lines.append('    private long _apkpySliceBound(String raw, long n, long step, boolean upper) {')
    lines.append('        if (raw == null || raw.trim().isEmpty()) {')
    lines.append('            if (step < 0) return upper ? -1 : n - 1;')
    lines.append('            return upper ? n : 0;')
