    def _used_overlay_names(cmds_list, result):
        for cmd in cmds_list or []:
            if not isinstance(cmd, dict):
                continue
            if cmd.get('type') in ('overlay_open', 'overlay_close') and cmd.get('overlay'):
                result.add(cmd['overlay'])
