    if _like_active:
        _like_jv = _get_jv_from_py_var(audio_like['button'])
        _liked_lit = '"' + _escape_java_literal(str(audio_like.get('liked', 'Liked'))) + '"'
        _unliked_lit = '"' + _escape_java_literal(str(audio_like.get('unliked', 'Like'))) + '"'
        lines.append("")
