        lines.append("                        else if (a.getSubAdminArea() != null) city = a.getSubAdminArea();")
        lines.append("                        else if (a.getAdminArea() != null) city = a.getAdminArea();")
        lines.append("                    }")
        lines.append("                } catch (Exception e) { }")
        lines.append("                final String fcity = city;")
